-- =====================================================================\n-- V11: correcciones que la Parte 2 dejó pendientes\n-- =====================================================================\n\n-- 1) Índices que los jobs diarios usan y no existían\nCREATE INDEX IF NOT EXISTS idx_dispute_lapsed\n  ON dispute_case (tenant_id, estado, response_deadline)\n  WHERE estado IN ('AWAITING_ACKNOWLEDGMENT','AWAITING_RESPONSE');\n\nCREATE INDEX IF NOT EXISTS idx_safety_open_incidents\n  ON safety_incident (tenant_id, status, occurred_at)\n  WHERE status IN ('REPORTED','UNDER_INVESTIGATION','CORRECTIVE_ACTIONS_OPEN');\n\n-- 2) Columna que el OshaDeadlineSweepJob necesita para no duplicar alertas\nALTER TABLE safety_incident\n  ADD COLUMN IF NOT EXISTS osha_deadline_alerted_at timestamptz,\n  ADD COLUMN IF NOT EXISTS osha_reported_at timestamptz;\n\n-- 3) Comentario de negocio en la tabla de auditoría para que un DBA entienda\nCOMMENT ON TABLE audit_event IS\n  'Append-only. La cadena se verifica con verify_audit_chain(tenant_id). '\n  'No se permite UPDATE ni DELETE: los triggers lo bloquean en producción.';\n\n-- 4) Trigger defensivo: audit_event append-only real\nCREATE OR REPLACE FUNCTION block_audit_mutation()\nRETURNS trigger AS $$\nBEGIN\n  RAISE EXCEPTION 'audit_event es append-only (%). No se permite % en producción.',\n    TG_TABLE_NAME, TG_OP;\nEND;\n$$ LANGUAGE plpgsql;\n\nDROP TRIGGER IF EXISTS trg_audit_no_update ON audit_event;\nCREATE TRIGGER trg_audit_no_update\n  BEFORE UPDATE OR DELETE ON audit_event\n  FOR EACH ROW EXECUTE FUNCTION block_audit_mutation();